         */domain: String, 
        /**
         * `qor1...` account.
         */address: String, uri: String, 
        /**
         * Chain id, e.g. `qorechain-vladi`.
         */chainId: String, 
        /**
         * At least 8 alphanumeric characters, chosen by the server.
         */nonce: String, 
        /**
         * ISO 8601 timestamp.
         */issuedAt: String, 
        /**
         * Optional scheme, e.g. `https`.
         */scheme: String? = nil, statement: String? = nil, 
        /**
         * `"1"` when set; null renders as `"1"`.
         */version: String? = nil, expirationTime: String? = nil, notBefore: String? = nil, requestId: String? = nil, resources: [String]? = nil) {
        self.domain = domain
        self.address = address
        self.uri = uri
        self.chainId = chainId
        self.nonce = nonce
        self.issuedAt = issuedAt
        self.scheme = scheme
        self.statement = statement
        self.version = version
        self.expirationTime = expirationTime
        self.notBefore = notBefore
        self.requestId = requestId
        self.resources = resources
    }
}

